************************************************************************************/

scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo;
scwin.clickBzProcsNo;
scwin.TR_JOB;
scwin.rowPos;
scwin.isurCd;
scwin.comNm;
scwin.listDd;
scwin.pJsMarket = $c.session.getUserInfo("market");
scwin.vScrenID = "ULDSTF05103.xml";
scwin.BTN_MAP = {
    "save": "btn_save"
};

scwin.onpageload = function () {
    scwin.init();
};

scwin.onpageunload = function () {
};

/* 
 * 화면 초기화
 */
scwin.init = async function () {
    panel_HDCOM_ISUR_CD.hide(); //미사용?
    if ($c.session.getUserInfo("market") === "1") {
        panel_KOSDAQ.hide();
        panel_KOSDAQ1.hide();
        panel_KSE.show();
    } else if ($c.session.getUserInfo("market") === "2") {
        panel_KOSDAQ.show();
        panel_KOSDAQ1.show();
        panel_KSE.hide();
    } else {
        scwin.pJsMarket = 'A';
    }
    await scwin.fn_searchCode();
    await scwin.fn_SetComboCode();
    // var parentWin = $c.win.getParent();
    var parentWin = $c.data.getParameter();
    scwin.vBzProcsNo = parentWin.clickBzProcsNo;
    scwin.rowPos = parentWin.rowPos;
    scwin.isurCd = parentWin.isurCd;
    scwin.comNm = parentWin.comNm;
    scwin.listDd = parentWin.listDd;

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    // buttonSet.setSaveInfo(btn_save, fn_save); // 저장
    // buttonSet.setDsclInfo(btn_dscl, fn_dscl); // 안내문작성

    //20100910 (2616) 회사정보 저장 후 '상장종목신규'버튼 활성화
    scwin.fn_btnShow(scwin.vBzProcsNo);
    if (scwin.vBzProcsNo != "") {
        // api 조회 대신 세팅을 해주면?
        ibx_searchCd.setValue(scwin.isurCd);
        ibx_searchNm.setValue(scwin.comNm);
        ibx_isurCd.setValue(scwin.isurCd);
        cal_listDd.setValue(scwin.listDd);

        await scwin.fn_read_sync();
        ibx_searchCd.setValue(dma_corpInfoRes.get("isurCd"));
        ibx_searchNm.setValue(dma_corpInfoRes.get("comNm"));
        sbx_secugrpId.setDisabled(true);

        //spac 여부에 따른 존립기간 _20100528
        if (sbx_spacYn.getValue() === "Y") {
            panel_spac.show();
        }
    } else {
        //존립기간disabled _20100528
        panel_spac.hide();
        sbx_secugrpId.setValue(parentWin.newSecugrpId); //부모창에서 증권그룹값이 가져온다.
        sbx_spotIsuTrdMktTpCd.setValue(scwin.pJsMarket);
        $c.util.setButtonState("grp_btnBox", "insert", scwin.BTN_MAP);
    }
};

scwin.fn_initForm = function (initTyp) {
    if (initTyp === "C") {
        // btn_coSearch.src = "../img/btn_search.gif";
        btn_coSearch.setDisabled(false);
    } else if (initTyp === "X") {
        // btn_coSearch.src = "../img/btn_search_d.gif";
        btn_coSearch.setDisabled(true);
    }
};

/* 
 * combo 데이터 세팅
 */
scwin.fn_SetComboCode = async function () {
    //주거래은행 목록
    const sbmOptions = {
        id: "sbm_listMaintradeBank",
        action: "/api/listing/common/code/list-maintrade-bank",
        method: "get",
        // ref: "dma_codReq",
        target: "dlt_listMaintradeBank=body",
        isProcessMsg: false
    };
    await $c.sbm.executeDynamic(sbmOptions);
};

/* 
 * 코드 리스트 세팅
 */
scwin.fn_searchCode = async function () {

    dma_codReq.set("codeList", "TRANSSTK_AGNT_CD, SPOT_ISU_TRD_MKT_TP_CD, EXT_AUDTR_CD, SECT_TP_CD, LIST_CLSS_CD, PRELM_INVSTG_COM_TP_CD"); //코드정보 List
    const sbmOptions = {
        id: "sbm_listCodeValue",
        action: "/api/listing/common/code/list-code-value",
        method: "get",
        ref: "dma_codReq",
        target: "dlt_transstkAgntCd=body.TRANSSTK_AGNT_CD, dlt_spotIsuTrdMktTpCd=body.SPOT_ISU_TRD_MKT_TP_CD, dlt_extAudtrCd=body.EXT_AUDTR_CD"
            + ", dlt_sectTpCd=body.SECT_TP_CD, dlt_listClssCd=body.LIST_CLSS_CD, dlt_prelmInvstgComTpCd=body.PRELM_INVSTG_COM_TP_CD",
        isProcessMsg: false
    };
    await $c.sbm.executeDynamic(sbmOptions);
};

scwin.fn_getLeadComNoStr = function () {
    return dma_corpInfoRes.get("leadcomMbrNmStr");
};

scwin.fn_setLeadComNMStr = function (str_no, str_nm) {
    dma_corpInfoRes.set("leadcomMbrNoStr", str_no);
    dma_corpInfoRes.set("leadcomMbrNmStr", str_nm);
    ibx_leadcomMbrNmStr.setValue(str_nm);
};

scwin.fn_GetParIsur = function (arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ibx_searchCd.getValue(); // 코드값을 포함할 컨트롤
    arrPar[1] = ibx_searchNm.getValue(); // 명칭값을 포함할 컨트롤
    arrPar[2] = sbx_secugrpId.getValue();
    arrPar[3] = sbx_spotIsuTrdMktTpCd.getValue();
    arrPar[4] = $c.lc.getGlbValue("SEARCH_TYP_SLC");
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

scwin.fn_SetParIsur = function (arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        ibx_searchCd.setValue(arrPar[0].ISUR_CD);
        ibx_searchNm.setValue(arrPar[0].COM_NM);
        scwin.fn_readKindStkNewRegNewList(arrPar[0].ISUR_CD);
    }
};



/**
 * 신규상장할 기업정보 조회 
*/
scwin.fn_readKindStkNewRegNewList = async function (ISUR_CD) {
    const reqMap = {
        isurCd: ISUR_CD
    };
    const sbmOptions = {
        id: "sbm_selectComInfo",
        action: "/api/listing/lstproc/realship/newlisting/select-corpinfo-byisurcd",
        method: "get",
        target: "dma_corpInfoRes=body",
        isProcessMsg: false
    };
    await $c.sbm.executeDynamic(sbmOptions, reqMap);

    scwin.dma_corpInfoRes_OnLoadCompleted();
};


/**
 * 선택회사의 법인, 주식발행내역 종목리스트 상세정보조회
 */
scwin.fn_read_sync = async function () {
    // await scwin.fn_readKindStkNewList();
    await scwin.fn_kindStkIsuDtl(ibx_isurCd.getValue(), cal_listDd.getValue());
};


/**
 * 신규상장 저장한 기업정보 조회
 * TO-BE 에서는 백에서 한번에 조회
*/
// scwin.fn_readKindStkNewList = function () {
//     // var url = "/KindStk.do?method=readKindStkNewList&inputMessageId=KIND_STK_NEWLIST_SEARCH_OUT";
//     // url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
//     // url += "&ISUR_CD=''";
//     // dma_corpInfoRes.DataID = encodeURI(url);
//     // dma_corpInfoRes.Reset();

//     // 이 api가 아닌거같다
//     dma_newListIsuSelectOneReq.set("bzProcsNo", scwin.vBzProcsNo);
//     const sbmOptions = {
//         id: "sbm_newListIsuSelectOne",
//         action: "/api/listing/lstproc/kind/listing-review/new-list-isu/select-one",
//         method: "get",
//         ref: "dma_newListIsuSelectOneReq",
//         target: "dma_newListIsuSelectOneRes=body",
//         // submitDoneHandler: scwin.sbm_newListIsuSelectOne_submitdone,
//         isProcessMsg: false
//     };
//     $c.sbm.executeDynamic(sbmOptions);
// };

/**
 * 선택회사의 주식발행내역 종목리스트 상세정보조회
 */
scwin.fn_kindStkIsuDtl = async function (vIsurCd, vLstDD) {
    dma_selectOneReq.set("bzProcsNo", scwin.vBzProcsNo);
    dma_selectOneReq.set("isurCd", vIsurCd);
    dma_selectOneReq.set("listDd", vLstDD);
    const sbmOptions = {
        id: "sbm_selectOne",
        action: "/api/listing/lstproc/kind/listing-review/stock/select-one",
        method: "get",
        ref: "dma_selectOneReq",
        target: "dlt_isuDetailRes=body.isuDetail, dma_corpInfoRes=body.corpInfo",
        // submitDoneHandler: scwin.sbm_selectOne_submitdone,
        isProcessMsg: false
    };
    let sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

    var vCurDate = $c.date.getServerDateTime();
    if (scwin.vBzProcsNo == "") {
        $c.util.setButtonState("grp_btnBox", "insert", scwin.BTN_MAP);
        scwin.fn_initForm('C');
    } else {
        scwin.fn_initForm('X');
        if (cal_listDd.getValue() > vCurDate) {
            // $c.util.setButtonState("grp_btnBox", "update", scwin.BTN_MAP);
            $c.util.setButtonState("grp_btnBox", "insert", scwin.BTN_MAP); //저장버튼 하나로통합?
        } else {
            //disable 시킨다.
            $c.util.setButtonState("grp_btnBox", "error", scwin.BTN_MAP);
        }
    }
    if (ibx_isurCd.getValue() == "") {
        $c.win.alert('보통주 상장심사가 선행되어야 합니다');
        $c.util.setButtonState("grp_btnBox", "error", scwin.BTN_MAP); //disable 시킨다.
        return;
    }
    if (ibx_listNo.getValue() != "") {
        // btn_listNo.src = "../img/btn_LstNoCrt_d.gif";
        btn_listNo.setDisabled(true);
    }
    if (ibx_fssUnqNo.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-0025", ""));
        $c.util.setButtonState("grp_btnBox", "error", scwin.BTN_MAP); //disable 시킨다.
    }

    if ($c.session.getUserInfo().depCd != '2500' && $c.session.getUserInfo().depCd != '2520' && $c.session.getUserInfo().depCd != '2540' &&
        $c.session.getUserInfo().depCd != '3300' && $c.session.getUserInfo().depCd != '3320' && $c.session.getUserInfo().depCd != '3330' &&
        $c.session.getUserInfo().depCd != '3E00' && $c.session.getUserInfo().depCd != '3E10' && $c.session.getUserInfo().depCd != '3E20' &&
        $c.session.getUserInfo().depCd != '3E30' && $c.session.getUserInfo().depCd != '3E40' &&
        $c.session.getUserInfo().depCd != '2615' && $c.session.getUserInfo().depCd != '3G20') {
        //심사1팀,심사2팀
        $c.util.setButtonState("grp_btnBox", "error", scwin.BTN_MAP); //disable 시킨다.
    }
};


/* 
 * 저장 유효성 확인
 */
scwin.fn_save = async function () {
    scwin.TR_JOB = 'I';
    if (!await $c.lc.isProcess(scwin.TR_JOB)) return;
    scwin.vBzProcsNo = await $c.stf.getNewBzProcNo();

    if (String(scwin.vBzProcsNo).length != 14) {
        await $c.win.alert($c.data.getMessage("com_complete_0151", "업무처리번호생성"));
    } else {
        dma_corpInfoRes.set("bzProcsNo", scwin.vBzProcsNo);
        scwin.fn_trs("I");
    }
};

/* 
 * 저장 기능
 */
scwin.fn_trs = async function (trsIdx) {
    if (cal_listDd.getValue() === "") {
        await $c.win.alert($c.data.getMessage("com_req_input", "상장일"));
        cal_listDd.focus();
        return false;
    }

    if (ibx_isurCd.getValue() === "") {
        await $c.win.alert($c.data.getMessage("com_req_input", "회사코드"));
        ibx_isurCd.focus();
        return false;
    }

    dma_corpInfoRes.set("listProcsStatCd", '20');

    dma_registerReq.set("bzProcsNo", dma_corpInfoRes.get("bzProcsNo"));
    dma_registerReq.set("listClssCd", dma_corpInfoRes.get("listClssCd"));
    dma_registerReq.set("listDd", dma_corpInfoRes.get("listDd"));
    dma_registerReq.set("prelmInvstgBzProcsNo", dma_corpInfoRes.get("prelmInvstgBzProcsNo"));
    dma_registerReq.set("isurCd", dma_corpInfoRes.get("isurCd"));
    dma_registerReq.set("spotIsuTrdMktTpCd", dma_corpInfoRes.get("spotIsuTrdMktTpCd"));

    const sbmOptions = {
        id: "sbm_register",
        action: "/api/listing/lstproc/kind/listing-review/stock/register",
        method: "post",
        ref: "dma_registerReq",
        isProcessMsg: false
    };
    let sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

    $c.win.alert($c.data.getParameter("com_complete_0150", "저장"));
    await scwin.fn_parentRefresh();

    //20100910 (2616) 회사정보 저장 후 '상장종목신규'버튼 활성화
    scwin.fn_btnShow(scwin.vBzProcsNo);
    if (scwin.TR_JOB == "U") {
        var parentWin = $c.win.getParent();
        //parentWin.dts_List.setFocusedCell(scwin.rowPos, 0);
        parentWin.grd_list.setFocusedCell(scwin.rowPos, 0);
    } else if (scwin.TR_JOB == "D") {
        // 삭제처리의 응답인 경우
        await $c.win.closePopup();
    } else {
        await scwin.fn_read_sync();
    }
};

/* 
 * 상장목목 확인
 */
scwin.fn_CheckBiz = function () {
    if (dlt_isuDetailRes.getTotalRow() == 0) {
        $c.win.alert("[상장종목]을 입력하세요.");
        return false;
    }
    return true;
};

scwin.fn_getKindStkDsclsTitle = function (vComNm, vListDD) {
    return "" + vComNm + " 종류주식,  상장일 " + vListDD.substring(0, 4) + "." + vListDD.substring(4, 6) + "." + vListDD.substring(6, 8) + "";
};


/**
 * 신규상장공시문생성조회
 */
scwin.fn_readKindStkCorpisuDiscls = function (dtsObj, vIsurCd, vLstDD) {
    //var url = "/KindStk.do?method=readDisclsData&inputMessageId=KIND_STK_NEWLIST_SEARCH_OUT";
    //url += "&ISUR_CD=" + vIsurCd;
    //url += "&LIST_DD=" + vLstDD;
    //dtsObj.DataID = encodeURI(url);
    //dtsObj.Reset();
};

/* 
 * 안내문작성 팝업
 */
scwin.fn_dscl = async function () {
    if (!scwin.fn_CheckBiz()) {
        return;
    }

    await $c.win.alert("공시안내문");
    return;

    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;
    scwin.fn_GetPar = function (arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        var Mkt_Id = dma_corpInfoRes.getCellData(dma_corpInfoRes.getRowPosition(), "spotIsuTrdMktTpCd");
        var List_Clss_Id = sbx_listClssCd.getValue();
        if (Mkt_Id == "1") {
            arr[0] = "68157";
            //test로 우선 신규상장
            //arr[0] = "68152A";

        } else if (Mkt_Id == "2") {
            arr[0] = "70735";
        }

        //arr[5] = fn_getKindStkDsclsTitle(getObjectValue(ibx_comNm), getObjectValue(cal_listDd));

        scwin.fn_readKindStkCorpisuDiscls(dts_Discls_Isu, ibx_isurCd.getValue(), cal_listDd.getValue());
        if (Mkt_Id == "1") {
            arr[5] = scwin.fn_getKindStkDsclsTitle(dts_Discls_Isu.getCellData(dts_Discls_Isu.getRowPosition(), "COM_NM"), cal_listDd.getValue());
        }
        $c.stf.CopyDataSet(dts_Discls_Isu, param_dts_isu);
        var dBzProcsNo = scwin.vBzProcsNo;
        for (var i = 1; i <= dlt_isuDetailRes.getTotalRow(); i++) {
            dBzProcsNo = dBzProcsNo + (dBzProcsNo == "" ? "" : ",") + dlt_isuDetailRes.getCellData(i, "BZ_PROCS_NO");
        }
        arr[1] = dBzProcsNo;
        arr[2] = dma_corpInfoRes.get("ISUR_CD");
        arr[3] = Mkt_Id;
        $c.stf.CopyDataSet(dma_corpInfoRes, param_dts_mst);
        for (i = 1; i <= param_dts_isu.getTotalRow(); i++) {
            param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "divReckDd1", param_dts_isu.getCellData(i, "divReckDd1"));
            param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "isuPrc", param_dts_isu.getCellData(i, "isuPrc"));
            param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "isuCd", param_dts_isu.getCellData(i, "isuCd"));
            param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "isuSrtCd", param_dts_isu.getCellData(i, "isuSrtCd"));
            param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "isuDd", param_dts_isu.getCellData(i, "isuDd"));
        }
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "listClssNm", sbx_listClssCd.getText());
        return arr.length;
    };
    scwin.fn_SetPar = function (arr) {

    };
    var wth = 730 + 5;
    var hgt = 785 + 30;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);

    // await $c.win.openPopup 함수로 전환 필요 : await $c.frame.CreateDialogFrame("ULDSTF92024gfm", "/listingcommon/ULDSTF92024.gfm", "종류주식 공시안내문작성", pt.x, pt.y, wth, hgt, "window");

    scwin.fn_GetPar = OldGet;
    scwin.fn_SetPar = OldSet;
};

/* 
 * 부모창 목록 조회
 */
scwin.fn_parentRefresh = function () {
    var fr_fn_list_sync = $c.win.getParent().scwin.fn_list_sync;
    fr_fn_list_sync();
};

scwin.fn_setBzProcsNo = function (obj) {
    scwin.clickBzProcsNo = dlt_isuDetailRes.getCellData(obj, "bzProcsNo");
    //alert("fn_setBzProcsNo():"+clickBzProcsNo);

};
scwin.fn_getBzProcsNo = function () {
    return scwin.clickBzProcsNo;
};

/* 
 * 20100910 (2616) 회사정보 저장 후 '상장종목신규'버튼 활성화
 */
scwin.fn_btnShow = function (val) {
    if (val != "") {
        //업무처리번호가 있음.
        btn_isuNew.setDisabled(false);
        btn_dscl.setDisabled(false);
        lab_btn.hide();
    } else {
        btn_isuNew.setDisabled(true);
        btn_dscl.setDisabled(true);
        lab_btn.show();
    }
};



/**
   신규상장할 기업선택
*/
scwin.fn_PopFindKindStkExamCorp = async function (pSecjGrpId) {
    // scwin.fn_GetPar = scwin.fn_GetParIsur;
    // scwin.fn_SetPar = scwin.fn_SetParIsur;
    const data = {
        isurCd: ibx_searchCd.getValue(), // 코드값을 포함할 컨트롤
        isurNm: ibx_searchNm.getValue(), // 명칭값을 포함할 컨트롤
        secugrpId: sbx_secugrpId.getValue(),
        mktTpCd: sbx_spotIsuTrdMktTpCd.getValue(),
        searchType: $c.lc.getGlbValue("SEARCH_TYP_SLC"),
    };
    const opts = {
        id: "ULDSTF05112",
        popupName: $c.lc.getSecuGrpNm(pSecjGrpId) + "종류주식 신규상장 법인 선택",
        width: 880,
        height: 700,
        frameModal: "top",
    };
    // STF05112 -> AS-IS: 발행기관 검색팝업, TO-BE: 주식예탁증서 저장??
    const res = await $c.win.openPopup("/ui/lst/kindstk/ULDSTF05112.xml", opts, data);

    if (res.isCloseButtonClick) return;

    ibx_searchCd.setValue(res.ISUR_CD);
    ibx_searchNm.setValue(res.COM_NM);
    scwin.fn_readKindStkNewRegNewList(res.ISUR_CD);

    await scwin.fn_read_sync();
};


/**
    종류주식 종목 등록(보호예수 포함)
*/
scwin.fn_OpenKindStkDetailCorpIsu_protect = async function (row) {
    var secugrpId = sbx_secugrpId.getValue();
    if (row >= 0) {
        //그리드에서 선택시
        scwin.fn_setBzProcsNo(row);
    } else {
        //신규버튼 선택시
        scwin.clickBzProcsNo = ""; //초기화

    }
