scwin.dma_corpInfoRes_OnLoadCompleted = function (rowcount) {
    var vCurDate = $c.date.getServerDateTime("yyyyMMdd");
    if (scwin.vBzProcsNo == "") {
        $c.util.setButtonState("grp_btnBox", "insert", scwin.BTN_MAP);
        scwin.fn_initForm('C');
    } else {
        scwin.fn_initForm('X');
        if (cal_listDd.getValue() > vCurDate) {
            // $c.util.setButtonState("grp_btnBox", "update", scwin.BTN_MAP);
            $c.util.setButtonState("grp_btnBox", "insert", scwin.BTN_MAP); //저장버튼 하나로통합?
        } else {
            $c.util.setButtonState("grp_btnBox", "error", scwin.BTN_MAP);
        }
    }
    if (ibx_isurCd.getValue() == "") {
        $c.win.alert('보통주 상장심사가 선행되어야 합니다');
        $c.util.setButtonState("grp_btnBox", "error", scwin.BTN_MAP);
        return;
    }
    if (ibx_listNo.getValue() != "") {
        btn_listNo.src = "../img/btn_LstNoCrt_d.gif";
        btn_listNo.setDisabled(true);
    }
    if (ibx_fssUnqNo.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-0025", ""));
        $c.util.setButtonState("grp_btnBox", "error", scwin.BTN_MAP);
    }
    if ($c.session.getUserInfo().depCd != '2500' && $c.session.getUserInfo().depCd != '2520' && $c.session.getUserInfo().depCd != '2540' &&
        $c.session.getUserInfo().depCd != '3300' && $c.session.getUserInfo().depCd != '3320' && $c.session.getUserInfo().depCd != '3330' &&
        $c.session.getUserInfo().depCd != '3E00' && $c.session.getUserInfo().depCd != '3E10' && $c.session.getUserInfo().depCd != '3E20' && $c.session.getUserInfo().depCd != '3E30' && $c.session.getUserInfo().depCd != '3E40' &&
        $c.session.getUserInfo().depCd != '2615' && $c.session.getUserInfo().depCd != '3G20') {
        //심사1팀,심사2팀
        $c.util.setButtonState("grp_btnBox", "error", scwin.BTN_MAP);
    }
};

scwin.sbx_spotIsuTrdMktTpCd_OnSelChange = function () {
    if (sbx_spotIsuTrdMktTpCd.getValue() == "1") {
        label_40.setValue("결산기");
        ibx_acntclsMm1.getDisplayFormatter("MM월 DD일");
