/* 
 * 상장번호생성 버튼
 */
scwin.btn_listNo_onclick = async function (e) {
    dma_selectNewListNoReq.set("spotIsuTrdMktTpCd", $c.session.getUserInfo("market")); //시장구분코드
    const sbmOptions = {
        id: "sbm_selectNewListNo",
        action: "/api/listing/lstproc/listinvstg-common/select-new-listno",
        method: "get",
        ref: "dma_selectNewListNoReq",
        target: "dma_selectNewListNoRes=body",
        isProcessMsg: false
    };
    await $c.sbm.executeDynamic(sbmOptions);

    scwin.sbm_selectNewListNo_submitdone();
};

/* 
 * 상장번호생성 버튼 콜백
 */
scwin.sbm_selectNewListNo_submitdone = function () {
    ibx_listNo.setValue(dma_selectNewListNoRes.get("listNo"));
}

/* 
 * 결산월 데이터 세팅
 */
scwin.acntclsMmFormatter = function () {
    let acntclsMmdd1 = dma_corpInfoRes.get("acntclsMmdd1");
    if ($c.util.isNotEmpty(acntclsMmdd1) && acntclsMmdd1.length === 2) {
        return acntclsMmdd1 + "월";
    } else if ($c.util.isNotEmpty(acntclsMmdd1) && acntclsMmdd1.length === 4) {
        return acntclsMmdd1.substring(0, 2) + "월" + acntclsMmdd1.substring(2, 4) + "일";
    }
}
